-- ============================================================
-- Company stock import (Option A): company-province warehouses
-- Auto-generated. Idempotent-ish: creates company/warehouses/buildings if missing,
-- and REPLACES BuildingInventory for the affected buildings.
-- ============================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;
DECLARE @whId INT, @bldId INT;

-- 0) Clean up any prior partial import of these company warehouses
DELETE bi FROM BuildingInventory bi
  JOIN WarehouseBuildings b ON b.Id = bi.BuildingId
  JOIN Warehouses w ON w.Id = b.WarehouseId
  WHERE w.Code LIKE 'ACC-%' OR w.Code LIKE 'PRO-%' OR w.Code LIKE 'SEB-%' OR w.Code LIKE 'KOG-%';
DELETE b FROM WarehouseBuildings b
  JOIN Warehouses w ON w.Id = b.WarehouseId
  WHERE w.Code LIKE 'ACC-%' OR w.Code LIKE 'PRO-%' OR w.Code LIKE 'SEB-%' OR w.Code LIKE 'KOG-%';
DELETE FROM Warehouses WHERE Code LIKE 'ACC-%' OR Code LIKE 'PRO-%' OR Code LIKE 'SEB-%' OR Code LIKE 'KOG-%';

-- 1) Ensure KOG operating company exists
IF NOT EXISTS (SELECT 1 FROM OperatingCompanies WHERE Code='KOG')
  INSERT INTO OperatingCompanies (Name, Code, Description, IsActive, CreatedAt)
  VALUES ('KOG Trading Enterprise', 'KOG', 'KOG Trading Enterprise stock', 1, SYSUTCDATETIME());

-- ==================== Access Medical ====================
-- Access Medical – KZN: 275 items
SET @whId = NULL; SET @bldId = NULL;
SELECT @whId = Id FROM Warehouses WHERE Code = 'ACC-KZN';
IF @whId IS NULL BEGIN
  INSERT INTO Warehouses (Name, Code, City, Province, Status, CreatedAt, UpdatedAt)
  VALUES ('Access Medical – KZN', 'ACC-KZN', 'Verulam', 'KwaZulu-Natal', 'Active', SYSUTCDATETIME(), SYSUTCDATETIME());
  SET @whId = SCOPE_IDENTITY();
END
SELECT @bldId = Id FROM WarehouseBuildings WHERE Code = 'ACC-KZN-01';
IF @bldId IS NULL BEGIN
  INSERT INTO WarehouseBuildings (WarehouseId, Code, Name, IsActive, CreatedAt, UpdatedAt)
  VALUES (@whId, 'ACC-KZN-01', 'Access Medical – KZN (Collective)', 1, SYSUTCDATETIME(), SYSUTCDATETIME());
  SET @bldId = SCOPE_IDENTITY();
END
DELETE FROM BuildingInventory WHERE BuildingId = @bldId;
