COMMIT;
PRINT 'Imported 1993 inventory rows across company-province warehouses.';
SELECT w.Code AS Warehouse, COUNT(bi.Id) AS Items, SUM(bi.QuantityOnHand) AS TotalQty
FROM Warehouses w JOIN WarehouseBuildings b ON b.WarehouseId=w.Id
JOIN BuildingInventory bi ON bi.BuildingId=b.Id
WHERE w.Code LIKE 'ACC-%' OR w.Code LIKE 'PRO-%' OR w.Code LIKE 'SEB-%' OR w.Code LIKE 'KOG-%'
GROUP BY w.Code ORDER BY w.Code;